export async function listNotesRows(): Promise<string | { message: string }> {
  return sqlQueryRaw("SELECT id, title, body FROM notes ORDER BY title", []);
}

export async function createNoteRows(input: CreateNoteInput): Promise<string | { message: string }> {
  return sqlQueryRaw("INSERT INTO notes (title, body) VALUES (?, ?) RETURNING id, title, body", [input.title, input.body]);
}

